<?php
declare(strict_types=1);

// Generated by scripts/release_crypto.py.
// RSA private operation + PKCS#1 v1.5 type 2 random padding.
// 插件 payload 只包含版本和运行时 seed，客户端连续 3 次校验失败会退出。

$RSA_E = '65537';
$RSA_P_HEX = '';
$RSA_Q_HEX = '';
$PAYLOAD_JSON = '{"v":"3.2.4","s":"49dd38c916b87fbd61cc5be36a1a5029abab35b782f930561dac258deccc4e6c"}';

function require_gmp(): void
{
    if (!extension_loaded('gmp')) {
        throw new RuntimeException('PHP GMP extension is required.');
    }
}

function gmp_from_bytes(string $bytes)
{
    $hex = bin2hex($bytes);
    return gmp_init($hex === '' ? '0' : $hex, 16);
}

function gmp_to_bytes($value, int $size): string
{
    $hex = gmp_strval($value, 16);
    if ((strlen($hex) % 2) !== 0) {
        $hex = '0' . $hex;
    }
    $bytes = hex2bin($hex);
    if ($bytes === false) {
        $bytes = '';
    }
    if (strlen($bytes) > $size) {
        return substr($bytes, -$size);
    }
    return str_pad($bytes, $size, "\x00", STR_PAD_LEFT);
}

function non_zero_random_bytes(int $length): string
{
    $result = '';
    while (strlen($result) < $length) {
        $chunk = random_bytes($length - strlen($result));
        $chunk = str_replace("\x00", '', $chunk);
        $result .= $chunk;
    }
    return $result;
}

function rsa_private_encrypt_pkcs1_v15(string $payload, string $pHex, string $qHex, string $eText): string
{
    require_gmp();
    $p = gmp_init($pHex, 16);
    $q = gmp_init($qHex, 16);
    $e = gmp_init($eText, 10);
    $n = gmp_mul($p, $q);
    $phi = gmp_mul(gmp_sub($p, 1), gmp_sub($q, 1));
    $d = gmp_invert($e, $phi);
    if ($d === false) {
        throw new RuntimeException('Invalid RSA parameters: e has no inverse.');
    }

    $modulusSize = intdiv(strlen(gmp_strval($n, 16)) + 1, 2);
    $maxPayloadSize = $modulusSize - 11;
    if (strlen($payload) > $maxPayloadSize) {
        throw new RuntimeException("Payload too large, max bytes: {$maxPayloadSize}");
    }

    $paddingSize = $modulusSize - strlen($payload) - 3;
    $encoded = "\x00\x02" . non_zero_random_bytes($paddingSize) . "\x00" . $payload;
    return gmp_to_bytes(gmp_powm(gmp_from_bytes($encoded), $d, $n), $modulusSize);
}

try {
    header('Content-Type: text/plain; charset=utf-8');
    echo base64_encode(rsa_private_encrypt_pkcs1_v15($PAYLOAD_JSON, $RSA_P_HEX, $RSA_Q_HEX, $RSA_E));
} catch (Throwable $e) {
    http_response_code(500);
    echo '检查更新失败，软件退出';
}
